// @vitest-environment node
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { APP_NAME, errorReportCopy } from "./privacy-copy";

// Regenerated by `hatchkit update` from the report allowlist. It names
// the app by its manifest slug; the page uses the display name.
const generated = readFileSync(
  new URL("../../../../.hatchkit/privacy-error-reports.md", import.meta.url),
  "utf8",
).replace(/^When \S+ hits/m, `When ${APP_NAME} hits`);

function listAfter(lead: string): string[] {
  const rest = generated.slice(generated.indexOf(lead) + lead.length);
  const items: string[] = [];
  for (const line of rest.trimStart().split("\n")) {
    if (!line.startsWith("- ")) break;
    items.push(line.slice(2));
  }
  return items;
}

describe("privacy page error-report copy", () => {
  it("lists what hatchkit's allowlist says a report contains and omits", () => {
    expect(errorReportCopy.contains).toEqual(listAfter("A report contains:"));
    expect(errorReportCopy.omits).toEqual(listAfter("A report never contains:"));
  });

  it("keeps the generated sentences", () => {
    expect(generated).toContain(errorReportCopy.when);
    expect(generated).toContain(errorReportCopy.ip);
  });
});
